static async IAsyncEnumerable<int> Count([EnumeratorCancellation] CancellationToken ct = default)
{
    for (int i = 1; i <= 3; i++)
    {
        await Task.Delay(10, ct);
        yield return i;
    }
}

await foreach (var n in Count()) Console.Write(n + " ");
// 1 2 3
